(async()=>{const out={};const fails=[];const CHK=(k,v)=>{out[k]=v;if(v!==true)fails.push(k+':'+JSON.stringify(v));};
const t0=Date.now();while(Date.now()-t0<4000&&(!T.$gameMap||!T.$gameMap.interpreter||!T.$gamePlayer)){await new Promise(r=>setTimeout(r,50));}
const a=T.$gameParty.battleMembers()[0];
out.hasActor=!!a;CHK('hasActor',out.hasActor===true);
if(!a){out.allOk=false;out.fails=fails;return JSON.stringify(out);}
/* 烟遁状态 16 stepsToRemove=256 */
const st16=T.$dataStates[16];out.steps16=st16?(st16.stepsToRemove||0):null;CHK('steps16is256',out.steps16===256);
a.addStateRaw(16);
out.hasState0=a.isStateAffected(16);CHK('stateAdded',out.hasState0===true);
/* 走 100 步:未到 256 不应解除 */
for(let i=0;i<100;i++)a.onMapStep();
out.hasAfter100=a.isStateAffected(16);CHK('stillAfter100',out.hasAfter100===true);
out.cnt100=a._stateSteps?a._stateSteps['s16']:null;
/* 再走 156 步(共256):应解除 */
for(let i=0;i<156;i++)a.onMapStep();
out.hasAfter256=a.isStateAffected(16);CHK('removedAt256',out.hasAfter256===false);
/* 真实行走接线:重新加持走 5 步仍保留 */
a.addStateRaw(16);for(let i=0;i<5;i++){if(T.$gamePlayer.canPass(T.$gamePlayer.x,T.$gamePlayer.y,6))T.$gamePlayer.moveStraight(6);else if(T.$gamePlayer.canPass(T.$gamePlayer.x,T.$gamePlayer.y,2))T.$gamePlayer.moveStraight(2);}
out.hasAfterWalk5=a.isStateAffected(16);CHK('keptAfterWalk5',out.hasAfterWalk5===true);
a.removeStateRaw(16);
out.allOk=fails.length===0;out.fails=fails;
return JSON.stringify(out);})()
